import csv,json,re
from pathlib import Path
from bs4 import BeautifulSoup,Comment
R=Path(__file__).resolve().parent
logs=list(csv.DictReader((R/'fetch_log.csv').open()))
by={x['attempt']:x for x in logs}
def source(key):
 x=by[key];return f"[{key}]({x['url']}) | {x['fetch_time_ET']}"
lines=['# JAX Weeks 1–8, 2026 / BAL defense — run B','', 'All network fetches used curl against public HTML pages. No login, private API, undocumented API, or PFF Premium was used. Raw responses, including errors/challenges, are in `raw/`. Times below are America/New_York with UTC offsets; they record request start. `fetch_log.csv` records every curl attempt, redirects, status, and curl exit. PFR requests were sequential with a 3-second sleep before each.','', '## Verified receiving game logs','', 'Values below are transcribed from fetched ESPN tables, not independently confirmed against NGS/PFR. Each row links to its source and records fetch time. ESPN labels all three logs **2026 Regular Season (JAX)**. Meyers therefore played for **JAX in every listed game**. Week 7 is a bye, not an observed zero-stat game.','', '| Player | Week | Date | Opponent | Team | Targets | Receptions | Yards | URL | Fetch time ET |','|---|---|---|---|---|---|---|---|---|---|']
for player in ['meyers','washington','strange']:
 s=BeautifulSoup((R/'raw'/f'espn_{player}.html').read_text(),'html.parser')
 for tr in s.select('table')[0].select('tr'):
  c=[x.get_text(' ',strip=True) for x in tr.find_all(['td','th'])]
  if not c or not c[0].startswith('Sun '):continue
  date=c[0].split()[-1];week={'9/13':1,'9/20':2,'9/27':3,'10/4':4,'10/11':5,'10/18':6,'11/1':8}[date]
  lines.append(f'| {player.title()} | {week} | {c[0]} | {c[1]} | JAX | {c[4]} | {c[3]} | {c[5]} | {source("espn_"+player)} |')
 lines.append(f'| {player.title()} | 7 | BYE | — | JAX (season affiliation) | N/A (bye) | N/A (bye) | N/A (bye) | {source("espn_jax_schedule")} |')
lines+=['','Schedule/week mapping and Week 7 bye source: '+source('espn_jax_schedule')+'. The fetched schedule labels the forthcoming Baltimore game Week 9; the requested directory name is retained. No Weeks 9+ stats are used.','','## Requested advanced metrics','','| Subject | Requested values | Result / reason | URL | Fetch time ET |','|---|---|---|---|---|']
for p in ['Meyers','Washington','Strange']:
 lines.append(f'| {p}, Weeks 1–8 | Average separation; cushion; share of team air yards; aDOT / average intended air yards | UNAVAILABLE: NGS HTML is an application shell; no player rows or metric data. Season sorted URL returned 404. All/week routes returned 200 shells. | {source("ngs_receiving_all")} |')
 lines.append(f'| {p}, Weeks 1–8 | PFR advanced receiving fields | UNAVAILABLE: HTTP 403 challenge; no regular or comment-hidden tables. | {source("pfr_"+p.lower())} |')
lines += [f'| Trevor Lawrence, Weeks 1–8 | Time to throw; aggressiveness | UNAVAILABLE: NGS passing pages return application shells without player metrics. | {source("ngs_passing_all")} |',f'| Trevor Lawrence, Weeks 1–8 | Pressure%; bad throw%; other advanced passing fields | UNAVAILABLE: PFR HTTP 403 challenge; no regular or comment-hidden tables. | {source("pfr_lawrence")} |',f'| BAL defense, Weeks 1–8 | Blitz%; pressure%; hurries; QB knockdowns (and rates if present) | UNAVAILABLE: PFR opponent page HTTP 403 challenge; no tables. No verified Week 1–8 aggregate. | {source("pfr_opp")} |',f'| JAX team, 2026 | Team receiving/passing cross-check | UNAVAILABLE: PFR team page HTTP 403 challenge. | {source("pfr_jax")} |','','## HTML/comment parsing audit','', 'BeautifulSoup parsed every saved response and separately parsed each HTML comment for `<table>` elements. The audit is saved in `parse_audit.json`. All six PFR responses have title “Just a moment...” and contain no tables, including in comments. Successful NGS responses contain no tables and expose only the NGS title as visible text; HTTP 200 does not establish data availability. No attempt was made to bypass the challenge or obtain backing API data.','','## Existing local images (visually inspected)','', 'These are existing artifacts, not fresh page fetches. Original capture time and full route-chart URL are UNAVAILABLE. Filenames supply week/opponent context where not visible in the crop. Route names below are visual interpretations of shapes, not official play-call classifications. Green tracks are after-catch movement, not additional routes.','','| File under `week10/ngs/` | Visible content / interpretation |','|---|---|','| `route_meyers_wk3_vsNE.png` | Chart explicitly labels Jakobi Meyers / 2026 vs Patriots. Shows crossing/in-breaking and out-breaking shapes across the shallow and intermediate field, with a blue touchdown marker in the intermediate middle. Green extensions show after-catch movement across the middle and toward the right side. Crop cuts off statistical totals. |','| `route_parker_washington_wk6.png` | Page explicitly labels Parker Washington, Jacksonville, Week 6, season 2026. Shows shallow lateral/crossing shapes near the line, intermediate breaks from both sides, and deeper stems/breaks on both sides. Several green paths run toward the left sideline and upfield. Cookie overlay dims the chart. |','| `route_strange_wk4_vsCIN.png` | Chart explicitly labels Brenton Strange / 2026 vs Bengals. Shows short flat/underneath shapes around and behind the line, intermediate diagonal/crossing and out-breaking shapes, and green extensions through the middle and toward the right sideline. Gray incomplete paths also appear. Crop cuts off statistical totals. |','| `receiving_table_page.webp` | Address bar shows `https://nextgenstats.nfl.com/stats/receiving/2026/REG/all/yards`. Table headers include CUSH, SEP, TAY, TAY%, REC, TAR and YDS. The visible player rows do not include Meyers, Washington or Strange. Thus their requested numbers are UNAVAILABLE from this image. Regular Season selection does not establish a Week 1–8 cutoff. |','','## Explicit missing-data list','','- NGS separation, cushion, team air-yard share and aDOT for each of Meyers, Washington and Strange, weekly and Week 1–8 aggregate: UNAVAILABLE; no values in fetched HTML or visible target-player screenshot rows.','- Lawrence NGS time to throw and aggressiveness, weekly and Week 1–8 aggregate: UNAVAILABLE; application shells only.','- BAL defensive blitz%, pressure%, hurries and QB knockdowns for Weeks 1–8: UNAVAILABLE; PFR blocked.','- PFR advanced receiving for all three players and Lawrence advanced passing (including pressure% and bad throw%): UNAVAILABLE; PFR blocked, comments empty of tables.','- Independent cross-source numerical confirmation of ESPN receiving logs: UNAVAILABLE; NGS/PFR did not supply accessible values.','- Week 7 receiving statistics: N/A because ESPN schedule explicitly shows BYE WEEK; no zeros invented.','- Local screenshot original capture times and full route-chart page URLs: UNAVAILABLE; not recorded in the images.','','## Complete fetch manifest','','| Attempt | URL | Fetch time ET | HTTP | Raw HTML |','|---|---|---|---|---|']
for x in logs:lines.append(f'| {x["attempt"]} | {x["url"]} | {x["fetch_time_ET"]} | {x["http_status"]} | [{x["raw_file"]}]({x["raw_file"]}) |')
(R/'notes_b.md').write_text('\n'.join(lines)+'\n')
audit=[]
for x in logs:
 p=R/x['raw_file'];s=BeautifulSoup(p.read_text(),'html.parser');comments=s.find_all(string=lambda t:isinstance(t,Comment))
 audit.append({'attempt':x['attempt'],'title':s.title.get_text() if s.title else None,'tables':len(s.find_all('table')),'comments':len(comments),'tables_in_comments':sum(len(BeautifulSoup(str(c),'html.parser').find_all('table')) for c in comments)})
(R/'parse_audit.json').write_text(json.dumps(audit,indent=2)+'\n')
print('Wrote notes_b.md and parse_audit.json;',len(logs),'logged fetches')
